\begin{corollary}[Local convergence of union averaged nonexpansive iterations]\label{cor:union averaged}
Let $T\colon X\setto X$ be union $\alpha$-averaged nonexpansive operator with $x^*\in\StrFix T$ and let $(\lambda_n)_{n\in\mathbb{N}}$ be a sequence in $(0, 1/\alpha]$ with $\liminf_{n\to\infty} \lambda_n(1/\alpha-\lambda_n)> 0$. Denote $r :=r(x^*;T)\in(0,+\infty]$ and consider $(x_n)_{n\in\mathbb{N}}$ with $x_0\in \inte\mathbb{B}(x^*;r)$ satisfying
\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1}\in (1-\lambda_n)x_n+\lambda_n T(x_n).
\end{equation*} 
Then $(x_n)_{n\in\mathbb{N}}$ converges to a point $\overline{x}\in\Fix T\cap \mathbb{B}(x^*;r)$. 
\end{corollary}

