\forall n\in\mathbb{N},\quad x_{n+1}\in (1-\lambda_n)x_n+\lambda_n T(x_n).
\end{equation*} 
Then $(x_n)_{n\in\mathbb{N}}$ converges to a point $\overline{x}\in\Fix T\cap \mathbb{B}(x^*;r)$. 
\end{theorem}

