In this section, we recall the necessary preliminaries for the subsequent sections. Unless stated otherwise, throughout this work we assume that
\begin{equation*}
\fcolorbox{gray!30}{gray!30}{  X\text{ is a (real) finite-dimensional Hilbert space}  }
\end{equation*}
with inner-product $\langle\cdot,\cdot\rangle$ and induced norm $\|\cdot\|$.

\begin{definition}[Averaged nonexpansive operators]
\label{def:averaged}
A single-valued operator $T\colon X\to X$ is said to be \emph{nonexpansive} if 
\begin{equation*}
\forall x,y\in X,\quad \|Tx-Ty\|\leq \|x-y\|,
\end{equation*}

and \emph{$\alpha$-averaged nonexpansive} if $\alpha\in(0,1)$ and
\begin{equation*}
\forall x,y\in X,\quad \|Tx-Ty\|^2 +\frac{1-\alpha}{\alpha}\|(\Id-T)x-(\Id-T)y\|^2 \leq \|x-y\|^2.
\end{equation*}
We say $T$ is \emph{averaged nonexpansive} if there is an $\alpha\in(0,1)$ such that $T$ is $\alpha$-averaged nonexpansive.
\end{definition}

\begin{proposition}[Characterizations of averaged nonexpansiveness]
\label{prop:AN characterizations}
Let $T\colon X\to X$ be an operator and let $\alpha\in(0,1)$. The following assertions are equivalent.
\begin{enumerate}[label =(\alph*)]
\item $T$ is $\alpha$-averaged nonexpansive.
\item $T =(1-\alpha)\Id+\alpha R$ for some nonexpansive operator $R\colon X\to X$.
\item $(1-1/\alpha)\Id+(1/\alpha)T$ is nonexpansive.
\end{enumerate}
\end{proposition}

\begin{proof}
Follows by combining \cite[Definition~4.33 and Proposition~4.35]{BauCom17}.
\end{proof}

\begin{definition}[Outer semicontinuity]
Let $X$ and $Y$ be Hilbert spaces. A set-valued map $\phi\colon X\setto Y$ is \emph{outer semicontinuous (osc)} at $\bar{x}$ if
\begin{equation*}
\phi(\bar{x}) \supseteq \Limsup_{x\to\bar{x}}\phi(x) :=\{y\in Y:\exists\,x_n\to \bar{x},\,\exists\,y_n\to y\text{ with }y_n\in \phi(x_n)\}. 
\end{equation*}  
That is, the limit supremum is understood in the sense of the Painlev\'e--Kuratowski outer limit on $X\times Y$.	
\end{definition}

\begin{definition}[Union averaged nonexpansive operators]\label{def:union averaged}
A set-valued operator $T\colon X\setto X$ is said to be \emph{union $\alpha$-averaged nonexpansive} (resp.\ \emph{union nonexpansive}) if $T$ can be expressed in the form
\begin{equation}\label{eq:def union averaged}
\forall x\in X,\quad T(x) =\{T_i(x): i\in\varphi(x)\},
\end{equation}
where $I$ is a finite index set, $\{T_i\}_{i\in I}$ is a collection of $\alpha$-averaged nonexpansive (resp.\ nonexpansive) operators on $X$, and $\varphi\colon X\setto I$, called an \emph{active selector}, is an osc operator with nonempty values.

As before, we say $T$ is \emph{union averaged nonexpansive} if there is an $\alpha\in(0,1)$ such that $T$ is union $\alpha$-averaged nonexpansive.
\end{definition}

In the following proposition, we take a closer look the structure of a class of set-valued operators which includes union averaged nonexpansive operators as a special case. Given a set-valued operator $T\colon X\setto X$, its \emph{single-valued set}, denoted by 
\begin{equation*}
\Sing T :=\{x\in X: T(x)\text{~is a singleton}\},
\end{equation*}
is the set of points at which $T$ is single-valued.

Using the results of the previous subsection, we now turn our attention convergence of iterations based on union nonexpansive operators. Throughout this subsection, we fix a particular representation for the considered operator. Let $T\colon X\setto X$ denote a union nonexpansive (resp.\ union $\alpha$-averaged nonexpansive) operator which we assume to be represented as
\begin{equation}\label{eq:a particular uan op}
T(x) =\{T_i(x):i\in\varphi(x)\},
\end{equation}
where $I$ is a finite index set, $\{T_i\}_{i\in I}$ is a collection of nonexpansive (resp.\ $\alpha$-averaged nonexpansive) operators on $X$, and $\varphi\colon X\setto I$ is the osc, nonempty-valued active selector. Fixing this representation is convenient because, in general, the representation of a union nonexpansive (resp.\ union $\alpha$-averaged nonexpansive) operator need not be unique and allows us to avoid repetition.

Corresponding to the representation \eqref{eq:a particular uan op}, we define the \emph{radius of attraction} of $T$ at a point $x^*\in X$ as
\begin{equation}\label{eq:radius of attraction}
r(x^*;T) :=\sup\{\delta>0: \forall x\in \mathbb{B}(x^*;\delta),\ \varphi(x)\subseteq\varphi(x^*)\}
\end{equation}

Here we note that radius of attraction is nonzero for a union nonexpansive operator (and hence too for a union averaged nonexpansive operator). In fact, we have that
\begin{equation*}
\forall x^*\in X,\quad r(x^*;T)\in (0,+\infty]
\end{equation*}
as is shown in the following proposition.

\begin{proposition}\label{prop:prop2.1 Tam17}
Let $\varphi\colon X\setto I$ for a finite set $I$ and let $x^*\in X$. Then $\varphi$ is outer semicontinuous at $x^*$ if and only if there exists $\delta>0$ such that
\begin{equation*}
\forall x\in\mathbb{B}(x^*;\delta),\quad \varphi(x)\subseteq\varphi(x^*).
\end{equation*}
Consequently, if $T\colon X\setto X$ is a union nonexpansive operator, then $r(x^*;T)\in (0,+\infty]$. 
\end{proposition}

\begin{proof}
This follows from \cite[Proposition~1]{Tam17}.
\end{proof}

\begin{proposition}[Equivalent characterizations of union averaged nonexpansiveness]
\label{prop:averaged}
Let $T\colon X\setto X$ be a set-valued operator and let $\alpha\in(0,1)$. The following assertions are equivalent.
\begin{enumerate}[label =(\alph*)]
\item $T$ is union $\alpha$-averaged nonexpansive.
\item\label{it:prop averaged 2} $T =(1-\alpha)\Id+\alpha R$ for some union nonexpansive operator $R\colon X\setto X$.
\item $(1-1/\alpha)\Id+(1/\alpha)T$ is union nonexpansive.
\end{enumerate}
\end{proposition}

\begin{proof}
Follows by combining Definition~\ref{def:union averaged} with Proposition~\ref{prop:AN characterizations}.
\end{proof}

\begin{proposition}[Active selectors, fixed points, single-valuedness]\label{prop:fixed points}
Let $T\colon X\setto X$ be a set-valued operator given by
\begin{equation*}
\forall x\in X,\quad T(x) =\{T_i(x): i\in \varphi(x)\}
\end{equation*}
where $I$ is a finite index set, $\varphi\colon X\setto I$ is an osc operator with nonempty values, and $\{T_i\}_{i\in I}$ is a collection of single-valued operators on $X$. The following assertions hold.
\begin{enumerate}[label =(\alph*)]

\item\label{it:fixed points_X} For each $i\in I$, the set $\varphi^{-1}(i)$ is closed. The space $X$ can be represented as
\begin{equation}
\label{eq:X is a union}
X =\bigcup_{i\in I}\varphi^{-1}(i).
\end{equation}

\item\label{it:fixed points_Fix} $x\in\Fix T$ if and only if there exists $i\in I$ such that $x\in\varphi^{-1}(i)\cap\Fix T_i$. Consequently, we have
\begin{equation*}
\Fix T =\bigcup_{i\in I}\left[\varphi^{-1}(i)\cap\Fix T_i\right]. 
\end{equation*}

\item\label{it:fixed points_StrFix} $x\in\StrFix T$ if and only if 
\begin{equation*}
x\in \bigcap_{i\in\varphi(x)}\Fix T_i =\bigcap_{i\in\varphi(x)} \left[\varphi^{-1}(i)\cap\Fix T_i\right].
\end{equation*}

\item\label{it:fixed points_StrFixSing} The strong fixed point set is the intersection of the fixed point set and the single-valued set, that is,
\begin{equation*}
\StrFix T =\Fix T\cap \Sing T.
\end{equation*}

\item\label{it:fixed points_Sing} If in addition $\{T_i\}_{i\in I}$ is a collection of continuous operators, then $T$ is ocs. Consequently,
\begin{equation*}
\Sing T =\left\{x\in X:\Limsup_{x'\to x}T(x')\text{ is singleton}\right\}.
\end{equation*}
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{it:fixed points_X}: Let $i\in I$ and consider a sequence $(x_n)_{n\in\mathbb{N}}\subseteq\varphi^{-1}(i)$ such that $x_n\to\overline{x}$. The definition of the inverse implies that $i\in\varphi(x_n)$ for all $n\in\mathbb{N}$ and, since $\varphi$ is osc, it holds that $i\in \varphi(\overline{x})$, which shows that $\varphi^{-1}(i)$ is closed and proves the first claim. The fact that \eqref{eq:X is a union} follows from the assumption that $\varphi(x)\neq \varnothing$ for all $x\in X$.

\ref{it:fixed points_Fix}: $x\in\Fix T\iff\exists i\in \varphi(x)$ such that $x\in\Fix T_i\iff\exists i\in I$ such that $x\in\varphi^{-1}(i)\cap\Fix T_i.$ 

\ref{it:fixed points_StrFix}: $x\in\StrFix T\iff x\in\Fix T_i$ for all $i\in\varphi(x)\iff x\in\varphi^{-1}(i)\cap\Fix T_i$ for all $i\in\varphi(x)$.

\ref{it:fixed points_StrFixSing}: Immediate from the respective definitions.

\ref{it:fixed points_Sing}: Fix $x\in X$. We first show that $T$ is osc. To this end, take $x_n\to x$ and $y_n\to y$ with $y_n\in T(x_n)$. Then the definition of $T$ ensures the existence of sequence $i_n\in \varphi(x_n)$ such that $y_n =T_{i_n}(x_n)\in T(x_n)$. Using the pigeonhole princple, we pass to a subsequence so that $y_{k_n} =T_i(x_{k_n})$ for fixed $i\in I$. The osc of $\varphi$ implies that $i\in\varphi(x)$ and continuity of $T_i$ gives
\begin{equation*}
y =\lim_{n\to\infty}y_{k_n} =\lim_{n\to\infty}T_i(x_{k_n}) =T_i(x)\in T(x),
\end{equation*}
which proves osc. The claimed formula for the singleton set follows since $x\in\Sing T\iff T(x)$ is singleton, and osc implies that $T(x) =\Limsup_{x'\to x}T(x')$. 
\end{proof}

\ref{it:fixed points_Sing}: Fix $x\in X$. We first show that $T$ is osc. To this end, take $x_n\to x$ and $y_n\to y$ with $y_n\in T(x_n)$. Then the definition of $T$ ensures the existence of sequence $i_n\in \varphi(x_n)$ such that $y_n =T_{i_n}(x_n)\in T(x_n)$. Using the pigeonhole princple, we pass to a subsequence so that $y_{k_n} =T_i(x_{k_n})$ for fixed $i\in I$. The osc of $\varphi$ implies that $i\in\varphi(x)$ and continuity of $T_i$ gives
\begin{equation*}
y =\lim_{n\to\infty}y_{k_n} =\lim_{n\to\infty}T_i(x_{k_n}) =T_i(x)\in T(x),
\end{equation*}
which proves osc. The claimed formula for the singleton set follows since $x\in\Sing T\iff T(x)$ is singleton, and osc implies that $T(x) =\Limsup_{x'\to x}T(x')$.

\begin{theorem}[Krasnosel'ski\u{\i}--Mann iterations with admissible control]
\label{thm:KM iterations with admissible control}
Let $I$ be a finite index set and let $\{T_i\}_{i\in I}$ be a collection of nonexpansive operators on $X$ with a common fixed point. Define a sequence $(x_n)_{n\in\mathbb{N}}$ with starting point $x_0\in X$ according to
\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1} :=(1-\lambda_n)x_n+\lambda_n T_{i_n}(x_n),
\end{equation*}
where $(i_n)_{n\in\mathbb{N}}$ is admissible in $I$, and $(\lambda_n)_{n\in\mathbb{N}}$ is in $(0, 1]$ with $\liminf_{n\to\infty}\lambda_n(1-\lambda_n)> 0$.
Then $(x_n)_{n\in\mathbb{N}}$ converges to a point $\overline{x}\in\cap_{i\in I} \Fix T_i$.
\end{theorem}

\begin{proof}
Since $\liminf_{n\to\infty}\lambda_n(1-\lambda_n)> 0$, there exists $n_0\in \mathbb{N}$ such that $\inf_{n\geq n_0}\lambda_n(1-\lambda_n)> 0$. By relabeling if necessary, we may assume without loss of generality that $\varepsilon :=\inf_{n\in\mathbb{N}}\lambda_n(1-\lambda_n)> 0$. 
Let $x\in \cap_{i\in I} \Fix T_i$ be arbitrary. Then, for all $n\in\mathbb{N}$, nonexpansiveness of $T_{i_n}$ yields
\begin{subequations} 
\begin{align*}
\|x_{n+1}-x\|^2& =\|(1-\lambda_n)(x_n-x)+\lambda_n(T_{i_n}(x_n)-x)\|^2 \\
& =(1-\lambda_n)\|x_n-x\|^2+\lambda_n\|T_{i_n}(x_n)-x\|^2-\lambda_n(1-\lambda_n)\|x_n-T_{i_n}(x_n)\|^2 \\
&\leq \|x_n-x\|^2-\varepsilon\|x_n-T_{i_n}(x_n)\|^2.
\end{align*}
\end{subequations}
It follows that $(\|x_n-x\|^2)_{n\in\mathbb{N}}$ is monotone nonincreasing, and hence convergent. Consequently, the sequence $(x_n)_{n\in\mathbb{N}}$ is bounded and 
\begin{equation}\label{eq:pre-asymp}
x_n-T_{i_n}(x_n)\to 0 \quad\text{as~} n\to\infty.
\end{equation}
Now, let $\overline{x}\in X$ be a cluster point of $(x_n)_{n\in\mathbb{N}}$. Then $(x_n)_{n\in\mathbb{N}}$ contains a convergent subsequence, say $(x_{k_n})_{n\in\mathbb{N}}$, with limit $\overline{x}$. 
We claim that $\overline{x}$ is an element of $\cap_{i\in I} \Fix T_i$. To this end suppose, by way of a contradiction, that $\overline{x}\not\in\cap_{i\in I} \Fix T_i$.
By passing to a further subsequence if necessary, we deduce that the sequence $(t_n)_{n\in\mathbb{N}}$ defined by
\begin{equation*}
t_n :=\min\{p\in\{k_n,\dots,k_{n+1}-1\}:\overline{x}\not\in\Fix T_{i_p}\}, 
\end{equation*}
is well defined.
Since $I$ is finite, by passing to yet another subsequence if necessary, we may assume that $i_{t_n} =\ell$ for all $n\in\mathbb{N}$ for some fixed index $\ell\in I$. 
Together with \eqref{eq:pre-asymp}, we deduce that
\begin{equation*}
x_{t_n}\to \overline{x} \text{~~~and~~~} (\Id-T_\ell)(x_{t_n})\to 0 \quad\text{as~} n\to\infty,
\end{equation*}
which, due to nonexpansiveness of $T_\ell$, implies that $\overline{x}\in\Fix T_\ell$. 
Thus a contradiction is obtained, and conclude that $\overline{x}\in\cap_{i\in I} \Fix T_i$. We then have that $(\|x_n-\overline{x}\|)_{n\in\mathbb{N}}$ is monotone nonincreasing and $\|x_{k_n}-\overline{x}\|\to 0$, and thus the conclusion follows.
\end{proof}

Let $x\in \cap_{i\in I} \Fix T_i$ be arbitrary. Then, for all $n\in\mathbb{N}$, nonexpansiveness of $T_{i_n}$ yields
\begin{subequations} 
\begin{align*}
\|x_{n+1}-x\|^2& =\|(1-\lambda_n)(x_n-x)+\lambda_n(T_{i_n}(x_n)-x)\|^2 \\
& =(1-\lambda_n)\|x_n-x\|^2+\lambda_n\|T_{i_n}(x_n)-x\|^2-\lambda_n(1-\lambda_n)\|x_n-T_{i_n}(x_n)\|^2 \\
&\leq \|x_n-x\|^2-\varepsilon\|x_n-T_{i_n}(x_n)\|^2.
\end{align*}
\end{subequations}

It follows that $(\|x_n-x\|^2)_{n\in\mathbb{N}}$ is monotone nonincreasing, and hence convergent. Consequently, the sequence $(x_n)_{n\in\mathbb{N}}$ is bounded and 
\begin{equation}\label{eq:pre-asymp}
x_n-T_{i_n}(x_n)\to 0 \quad\text{as~} n\to\infty.
\end{equation}

Together with \eqref{eq:pre-asymp}, we deduce that
\begin{equation*}
x_{t_n}\to \overline{x} \text{~~~and~~~} (\Id-T_\ell)(x_{t_n})\to 0 \quad\text{as~} n\to\infty,
\end{equation*}
which, due to nonexpansiveness of $T_\ell$, implies that $\overline{x}\in\Fix T_\ell$.

